    buy_book = []
    sell_book = []
    order_map = {}

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, remaining_qty, arrival_time = order_map[order_id]
                if side == 'buy':
                    buy_book = [o for o in buy_book if o[2] != order_id]
                else:
                    sell_book = [o for o in sell_book if o[2] != order_id]
                del order_map[order_id]

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]
            arrival_time = len(orders)

